}

function runWithCallback(input, state) {
  const { svc, log } = makeServices(state);
  return new Promise((resolve) => {
    signUp(input, svc, (err, value) => resolve(err ? { error: err.message, calls: log.slice() } : { value, calls: log.slice() }));
  });
}

