'use strict';

function fulfilOrder(order, svc, cb) {
  svc.store.getItem(order.sku, (err, item) => {
    if (err) return cb(err);
    if (!item) return cb(new Error('unknown sku ' + order.sku));
    if (item.stock < order.qty) return cb(new Error('only ' + item.stock + ' left of ' + order.sku));
    svc.pricing.quote(item, order.qty, (err, price) => {
      if (err) return cb(new Error('pricing failed: ' + err.message));
      const total = price.unit * order.qty + price.shipping;
      if (order.budget !== undefined && total > order.budget) return cb(new Error('over budget: ' + total));
      svc.store.reserve(order.sku, order.qty, (err, left) => {
        if (err) return cb(err);
        const afterMailerSend = () => {
          svc.audit.note('fulfilled ' + order.sku, (err) => {
            if (err) return cb(err);
            svc.ledger.record({ sku: order.sku, total }, (err, entries) => {
              if (err) return cb(err);
              cb(null, { sku: order.sku, total, left, entries, notified: Boolean(order.email) });
            });
          });
        };
        if (order.email) {
          svc.mailer.send(order.email, 'Order ' + order.sku, (err) => {
            if (err) return cb(new Error('mail failed: ' + err.message));
            afterMailerSend();
          });
        } else {
          afterMailerSend();
        }
      });
    });
  });
}

module.exports = { fulfilOrder };

