'use strict';

function signUp(request, svc, cb) {
  svc.users.findByEmail(request.email, (err, existing) => {
    if (err) return cb(err);
    if (existing) return cb(new Error('email already registered: ' + request.email));
    svc.quota.check(request.plan, (err, quota) => {
      if (err) return cb(new Error('quota lookup failed: ' + err.message));
      if (quota !== undefined && quota.used >= quota.limit) return cb(new Error('no seats left on ' + request.plan));
      svc.hasher.hash(request.password, (err, hash) => {
        if (err) return cb(new Error('hashing failed: ' + err.message));
        svc.users.create({ email: request.email, hash, plan: request.plan }, (err, user) => {
          if (err) return cb(err);
          const afterMailerWelcome = () => {
            svc.audit.log('signup ' + user.id, (err) => {
              if (err) return cb(err);
              cb(null, { id: user.id, plan: request.plan });
            });
          };
          if (request.plan !== 'free') {
            svc.mailer.welcome(request.email, (err) => {
              if (err) return cb(new Error('welcome mail failed: ' + err.message));
              afterMailerWelcome();
            });
          } else {
            afterMailerWelcome();
          }
        });
      });
    });
  });
}

module.exports = { signUp };

