'use strict';

function buildReport(req, svc, cb) {
  svc.warehouse.stock(req.site, (err, stock) => {
    if (err) return cb(new Error('warehouse: ' + err.message));
    if (stock === undefined) return cb(new Error('unknown site ' + req.site));
    svc.sales.week(req.site, (err, sales) => {
      if (err) return cb(new Error('sales: ' + err.message));
      const sold = sales.reduce((a, b) => a + b, 0);
      svc.forecast.predict(stock, sales, (err, forecast) => {
        if (err) return cb(new Error('forecast: ' + err.message));
        const weeksLeft = forecast.perWeek === 0 ? null : Math.floor(stock / forecast.perWeek);
        const afterNotesFlag = () => {
          svc.cache.put('report:' + req.site, { stock, sold, weeksLeft }, (err) => {
            if (err) return cb(err);
            cb(null, { site: req.site, stock, sold, weeksLeft });
          });
        };
        if (weeksLeft !== null && weeksLeft < req.weeks) {
          svc.notes.flag(req.site, weeksLeft, (err) => {
            if (err) return cb(new Error('notes: ' + err.message));
            afterNotesFlag();
          });
        } else {
          afterNotesFlag();
        }
      });
    });
  });
}

module.exports = { buildReport };

