const { fulfilOrder } = require('../src/fulfil.js');

function run(input, state) {
  const { svc, log } = makeServices(state);
  return fulfilOrder(input, svc).then(
    (value) => ({ value, calls: log.slice() }),
    (err) => ({ error: err.message, calls: log.slice() }),
  );
}

function runWithCallback(input, state) {
  const { svc, log } = makeServices(state);
  return new Promise((resolve) => {
    fulfilOrder(input, svc, (err, value) => resolve(err ? { error: err.message, calls: log.slice() } : { value, calls: log.slice() }));
  });
}

