'use strict';

function call(obj, method, ...args) {
  return new Promise((resolve, reject) => {
    obj[method](...args, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

async function fulfilOrderAsync(order, svc) {
  const item = await call(svc.store, 'getItem', order.sku);
  if (!item) throw new Error('unknown sku ' + order.sku);
  if (item.stock < order.qty) throw new Error('only ' + item.stock + ' left of ' + order.sku);
  let price;
  try {
    price = await call(svc.pricing, 'quote', item, order.qty);
  } catch (err) {
    throw new Error('pricing failed: ' + err.message);
  }
  const total = price.unit * order.qty + price.shipping;
  if (order.budget !== undefined && total > order.budget) throw new Error('over budget: ' + total);
  const left = await call(svc.store, 'reserve', order.sku, order.qty);
  const entries = await call(svc.ledger, 'record', { sku: order.sku, total });
  return { sku: order.sku, total, left, entries, notified: Boolean(order.email) };
}

// Promise when called without a callback, node-style callback otherwise.
function fulfilOrder(order, svc, cb) {
  const promise = fulfilOrderAsync(order, svc);
  if (typeof cb !== 'function') return promise;
  promise.then((value) => cb(null, value), (err) => cb(err));
}

module.exports = { fulfilOrder };

