'use strict';

function call(obj, method, ...args) {
  return new Promise((resolve, reject) => {
    obj[method](...args, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

async function signUp(request, svc) {
  const existing = await call(svc.users, 'findByEmail', request.email);
  if (existing) throw new Error('email already registered: ' + request.email);
  let quota;
  try {
    quota = await call(svc.quota, 'check', request.plan);
  } catch (err) {
    throw new Error('quota lookup failed: ' + err.message);
  }
  if (quota !== undefined && quota.used >= quota.limit) throw new Error('no seats left on ' + request.plan);
  let hash;
  try {
    hash = await call(svc.hasher, 'hash', request.password);
  } catch (err) {
    throw new Error('hashing failed: ' + err.message);
  }
  const user = await call(svc.users, 'create', { email: request.email, hash, plan: request.plan });
  if (request.plan !== 'free') {
    try {
      await call(svc.mailer, 'welcome', request.email);
    } catch (err) {
      throw new Error('welcome mail failed: ' + err.message);
    }
  }
  return { id: user.id, plan: request.plan };
}

module.exports = { signUp };

