'use strict';

function call(obj, method, ...args) {
  return new Promise((resolve, reject) => {
    obj[method](...args, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

async function buildReport(req, svc) {
  let stock;
  try {
    stock = await call(svc.warehouse, 'stock', req.site);
  } catch (err) {
    throw new Error('warehouse: ' + err.message);
  }
  if (stock === undefined) throw new Error('unknown site ' + req.site);
  let sales;
  try {
    sales = await call(svc.sales, 'week', req.site);
  } catch (err) {
    throw new Error('sales: ' + err.message);
  }
  const sold = sales.reduce((a, b) => a + b, 0);
  let forecast;
  try {
    forecast = await call(svc.forecast, 'predict', stock, sales);
  } catch (err) {
    throw new Error('forecast: ' + err.message);
  }
  const weeksLeft = forecast.perWeek === 0 ? null : Math.floor(stock / forecast.perWeek);
  if (weeksLeft !== null && weeksLeft < req.weeks) {
    try {
      await call(svc.notes, 'flag', req.site, weeksLeft);
    } catch (err) {
      throw new Error('notes: ' + err.message);
    }
  }
  await call(svc.cache, 'put', 'report:' + req.site, { stock, sold, weeksLeft });
  return { site: req.site, stock, sold, weeksLeft };
}

module.exports = { buildReport };

