const { buildReport } = require('../src/report.js');

function run(input, state) {
  const { svc, log } = makeServices(state);
  return buildReport(input, svc).then(
    (value) => ({ value, calls: log.slice() }),
    (err) => ({ error: err.message, calls: log.slice() }),
  );
}

function runWithCallback(input, state) {
  const { svc, log } = makeServices(state);
  return new Promise((resolve) => {
    buildReport(input, svc, (err, value) => resolve(err ? { error: err.message, calls: log.slice() } : { value, calls: log.slice() }));
  });
}

